#!/usr/bin/env python3
"""Build the static Pages site. Editorial text is intentionally version controlled."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1]
NFL = 'https://www.nfl.com/players/bo-nix/stats/career'
