INJURY = 'https://www.nfl.com/injuries/league/2026/reg7'
TIME = 'https://scikit-learn.org/stable/modules/generated/sklearn.model_selection.TimeSeriesSplit.html'
LEAK = 'https://scikit-learn.org/stable/common_pitfalls.html'
METRIC = 'https://scikit-learn.org/stable/modules/model_evaluation.html'
CAL = 'https://scikit-learn.org/0.21/modules/calibration.html'
NIST = 'https://tsapps.nist.gov/publication/get_pdf.cfm?pub_id=921446'
