HARM = 'https://www.gamblingcommission.gov.uk/report/qualitative-follow-up-interviews-with-participants-from-the-gambling-survey/qualitative-gsgb-experimental-statistics-phase-interrelation-of-different'
PAGES = 'https://docs.github.com/en/pages/getting-started-with-github-pages/using-custom-workflows-with-github-pages'

nav = [('index.html','Overview','01'),('strategies.html','Strategies','02'),('validation.html','Validation','03'),('correlation.html','Correlation','04'),('evidence.html','Evidence library','05'),('review.html','Flagged for review','06')]
def source(url, label='Source ↗'):
    return f'<a class="source" href="{escape(url, quote=True)}" target="_blank" rel="noopener noreferrer">{escape(label)}</a>'
def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>' + ''.join(f'<th scope="col">{x}</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{cell}</td>' for cell in row) + '</tr>' for row in rows) + '</tbody></table></div>'
def pill(text, typ='pending'): return f'<span class="pill {typ}"><span></span>{text}</span>'
def section(kicker,title,desc=''):
    return f'<div class="section-heading"><div><div class="eyebrow">{kicker}</div><h2>{title}</h2></div>{f"<p>{desc}</p>" if desc else ""}</div>'
def layout(filename, title, subtitle, body):
    links = ''.join(f'<a class="nav-link {"active" if filename == url else ""}" href="{url}" {"aria-current=page" if filename == url else ""}><span class="nav-number">{number}</span>{label}<span class="nav-arrow">↗</span></a>' for url,label,number in nav)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A source-led NFL line origination research dashboard."><title>{title} — Line / Lab</title><link rel="stylesheet" href="assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><div class="shell"><aside class="sidebar"><a class="brand" href="index.html"><span class="brand-mark">L<span>/</span>L</span><span>LINE / LAB<small>NFL RESEARCH DESK</small></span></a><div class="side-label">WORKSPACE <span>2026</span></div><nav aria-label="Main navigation">{links}</nav><div class="sidebar-bottom"><span class="status-dot"></span> Research mode <p>Built for evidence, not certainty.</p></div></aside><div class="content"><header class="topbar"><span>RESEARCH DESK <span class="slash">/</span> {title.upper()}</span><span class="top-right"><i></i> STATIC RESEARCH SNAPSHOT</span></header><main id="main"><div class="page-header"><div class="eyebrow">NFL LINE ORIGINATION <span class="orange">/</span> RESEARCH WORKSPACE</div><h1>{title}</h1><p>{subtitle}</p></div>{body}<footer><span>LINE / LAB <span class="slash">/</span> RESEARCH DESK</span><span>Evidence before edge. <a href="review.html">See limitations ↗</a></span></footer></main></div></div></body></html>'''

home = '''<div class="hero"><div class="hero-main"><div class="hero-tag"><span></span> THE EXECUTIVE BRIEF</div><h2>Better questions.<br><em>More defensible lines.</em></h2><p>A research framework for originating NFL probabilities, comparing strategies, and separating a repeatable signal from a lucky result.</p><div class="hero-actions"><a class="button light" href="strategies.html">Explore strategies <span>↗</span></a><a class="text-button" href="validation.html">See the validation process →</a></div></div><div class="hero-side"><div class="hero-side-top">RESEARCH STATUS <span>●</span></div><div class="hero-big">Not yet<br>validated<span>.</span></div><p>No strategy has passed the gates. No bets or rewards are being issued.</p><div class="hero-side-foot">LAST REVIEWED <strong>01 NOV 2026</strong></div></div></div>
<div class="metrics"><div><span>STRATEGY CANDIDATES</span><strong>03</strong><small>Hypotheses, not recommendations</small></div><div><span>VALIDATED STRATEGIES</span><strong>00</strong><small>Evidence not yet available</small></div><div><span>MEASURED CORRELATIONS</span><strong>—</strong><small>Insufficient paired data</small></div><div><span>MODE</span><strong class="mode">Research</strong><small>No live odds or automation</small></div></div>
''' + section('01 / THE THESIS','A disciplined path to an edge','Separate what is known today from what still needs to be tested.') + '''<div class="three-cards"><article><div class="card-num">01 <span>↗</span></div><h3>Originate the line</h3><p>Estimate a full outcome distribution using only information available before a fixed decision time. Derive fair probabilities and prices from it.</p><a href="strategies.html">VIEW CANDIDATES →</a></article><article><div class="card-num">02 <span>↗</span></div><h3>Test against a baseline</h3><p>Use time-ordered, untouched evaluations and proper probability scores. Model selection belongs inside the training window.</p><a href="validation.html">VIEW THE GATES →</a></article><article><div class="card-num">03 <span>↗</span></div><h3>Respect dependence</h3><p>Same-game outcomes can move together. A joint model needs evidence; multiplying marginal probabilities is not generally valid.</p><a href="correlation.html">VIEW CORRELATION →</a></article></div>
<div class="split-section"><div>''' + section('02 / BOTTOM LINE','What we know') + '''<p class="body-copy">The repository began as a single-line README. This research edition adds a sourced evidence sample and a proposed competition design—not a working data feed, prediction engine, or proof of betting skill.</p><a class="inline-link" href="evidence.html">Browse the evidence library →</a></div><div class="notice"><span class="notice-icon">!</span><div><strong>Uncertainty is not a defect.</strong><p>Luck cannot be eliminated from sporting outcomes. Repeated out-of-sample testing and uncertainty intervals can help distinguish skill from noise, but cannot guarantee profitability.</p><a href="review.html">Review open limitations ↗</a></div></div></div>'''

strategy_rows = [
['<strong>S01</strong><br>Game line','Single bet','Model home and away score distributions from pregame team strength, availability and venue; derive moneyline, spread and total probabilities.','Compare with a timestamped, de-vigged two-sided market baseline.','Not tested',source(SCHEDULE)],
['<strong>S02</strong><br>Game portfolio','Parlay','Estimate a joint distribution across selected game outcomes. Test the joint event directly rather than assuming independence.','Compare with a calibrated independent-marginal benchmark and actual offered parlay price.','Not tested',source(NIST)],
['<strong>S03</strong><br>Player usage','Player prop combo','Model opportunities and efficiency jointly for player outcomes, conditional on participation and game context.','Evaluate each marginal and the joint event; account for book-specific void and settlement rules.','Not tested',source(KELCE)],
]
strategies = '<div class="callout"><b>Research candidates, not picks.</b> Inputs, prices, historical snapshots and settlement rules have not been assembled. No edge, rank or return is claimed.</div>' + section('01 / CANDIDATE BOOK','Three testable strategies','Each candidate is a proposed model, not an NFL-endorsed method.') + table(['ID / MODEL','MARKET','SIGNAL DESIGN','COMPARISON','STATUS','METHOD CONTEXT'],strategy_rows) + section('02 / PRICING LOGIC','From forecasts to fair prices') + '''<div class="detail-grid"><article><span class="step">01</span><h3>Define the contract</h3><p>Specify market, threshold, overtime, push, void and payout terms. Treat participation and settlement as part of the event definition.</p></article><article><span class="step">02</span><h3>Price the outcome</h3><p>For a binary no-push contract, fair decimal odds = 1 / p. Expected net return per unit at decimal odds d = p × d − 1. For push/void outcomes, model all settlement states explicitly.</p></article><article><span class="step">03</span><h3>Compare responsibly</h3><p>Compare against an executable timestamped quote and its rules, including margin. For a two-sided no-push market, proportional de-vig uses implied q / (q₁ + q₂); it is an approximation, not an observed true probability.</p></article></div><p class="caption">The pricing arithmetic is a proposed analytical convention; the regulator explains why rules, payouts and likelihood matter. '''+source(RULES,'Read regulator guidance ↗')+'''</p><div class="notice wide"><span class="notice-icon">!</span><div><strong>Never interpret a missing price as zero.</strong><p>The system must abstain when price, time, rules, availability or reliable inputs are missing. This site does not place bets.</p></div></div>'''

gate_rows = [
['G01','Provenance','Require official source, retrieval time, event ID, timestamp and recorded contract rules. Reject missing or unverifiable fields.','Pending',source(LEAK)],
['G02','Time integrity','Freeze pre-decision snapshots. Fit transforms, feature selection and tuning only on prior training data; keep games together.','Pending',source(TIME)],
['G03','Calibration','Require a forecast for every eligible competition event, even when the betting policy abstains; score log loss and Brier score and inspect reliability and sample counts.','Pending',source(METRIC)],
['G04','Baseline','Pre-register a matched market baseline; require lower holdout log loss than baseline and a positive lower 95% paired game-block bootstrap interval for baseline minus model loss.','Pending',source(METRIC)],
['G05','Robustness','Evaluate across multiple forward folds and a final locked future holdout; block-bootstrap games and report uncertainty, subgroups and drift. Correct for the candidate selection process.','Pending',source(TIME)],
['G06','Settlement &amp; risk','Replay actual available prices, commission, limits, pushes and voids; report net returns and drawdown separately from forecast skill. Abstain on missing rules.','Pending',source(RULES)],
]
validation = '<div class="callout"><b>All gates are pending.</b> These are project proposals, not validated thresholds or claims that a source prescribes them. A failed or unmeasurable gate means no award.</div>' + section('01 / ADMISSION RULES','Validation gates','Apply to each model and each market before it enters a leaderboard.') + table(['GATE','NAME','PROPOSED REQUIREMENT','STATUS','METHOD CONTEXT'],gate_rows) + section('02 / COMPETITION DESIGN','A leaderboard built for skill') + '''<div class="two-cards"><article><div class="eyebrow">SCORING</div><h3>Reward forecast quality, not lucky wins.</h3><p>For each eligible common event, use score improvement = baseline log loss − model log loss. Higher is better. Rank only candidates that pass every gate; report the matched sample and interval. Require a pre-registered minimum sample by market before evaluation; no minimum has been set or tested.</p></article><article><div class="eyebrow">REWARDS</div><h3>Keep the prize pool hypothetical.</h3><p>Proposed: award fixed non-cash research credits to the top eligible strategy after the locked evaluation period. If none passes, award nothing. Pool size, tie rules and eligibility must be fixed before a future contest; none currently exists.</p></article></div><div class="prose"><h3>Evaluation protocol</h3><ol><li>Register candidates, eligible event universe, timestamps, frozen market baseline and metrics before observing outcomes.</li><li>Use expanding training windows, time-ordered validation and a final untouched holdout. Group all legs in a game; preserve forecast-time availability and archive corrections.</li><li>Calibrate on a separate earlier window. Never tune on the final holdout. Require forecasts for all eligible events even when the betting policy abstains; compare the same events to avoid cherry-picking. Missing competition forecasts make a candidate ineligible.</li><li>Quantify uncertainty with paired game-block resampling and account for candidate selection using nested evaluation or a multiple-testing procedure specified in advance. Report realized ROI as secondary, not proof of skill.</li></ol><p>Log loss for binary outcome y and forecast p is −[y log(p) + (1 − y) log(1 − p)]; probabilities must be strictly between 0 and 1. Loss comparisons require identical settled event definitions; pushes and voids need separate handling. '''+source(METRIC,'Metrics documentation ↗')+'''</p><p>These controls reduce overfitting and luck-driven selection; they cannot remove randomness or guarantee future performance. '''+source(NIST,'NIST on forecasting ↗')+'''</p></div>'''

corr_rows = [
['Quarterback passing yards / receiver yards','Same game; paired player outcomes','','','Unverified — no paired dataset',source(KELCE)],
['Team score / game total','Same game; settled final scores','','','Unverified — no paired dataset',source(HURTS)],
['Two selections across games','Matched game-week outcomes','','','Unverified — no paired dataset',source(SCHEDULE)],
]
correlation = '<div class="callout"><b>Blank is intentional.</b> No correlation values have been estimated or independently verified. Example pairings are research hypotheses, not claims about direction or strength.</div>' + section('01 / DEPENDENCE REGISTER','Correlation candidates','No observed value should be inferred from the relationships below.') + table(['PAIR','UNIT / DEFINITION','N','CORRELATION','STATUS','OFFICIAL CONTEXT'],corr_rows) + '''<div class="prose"><h3>How to estimate, when evidence exists</h3><ol><li>Collect official, paired, game-level outcomes; document population, season, participation, timestamps and exclusions. Missing is not zero.</li><li>For continuous outcomes compute Pearson r = covariance(X,Y) / (sd(X) × sd(Y)); for binary outcomes use the same formula on 0/1 indicators. If a variance is zero, report undefined, not zero.</li><li>Estimate only on training-period data; use game-block bootstrap intervals and report n, time period and selection criteria. Compare with holdout joint-event calibration and score, not correlation alone.</li><li>For two binary legs, P(A and B) = pA × pB + r × √[pA(1−pA)pB(1−pB)]. This identity requires a valid correlation consistent with the marginals; it does not generalize to pricing all higher-order combinations from pairwise correlations alone.</li></ol><p>Correlation is not causation, and historic fit does not ensure good forecasts. '''+source(NIST,'Read NIST caution ↗')+'''</p></div><div class="notice wide"><span class="notice-icon">!</span><div><strong>Joint pricing requires more than a correlation matrix.</strong><p>For three or more legs, estimate and test a coherent multivariate joint distribution. Evaluate tail probabilities, participation, pushes, and bookmaker rules explicitly.</p></div></div>'''

evidence_rows = [
['NFL official career stats','Bo Nix, Denver; 2024 passing','17 games; 567 attempts; 376 completions; 3,775 yards; 29 TD; 12 INT','Verified as displayed; season aggregate only',source(NFL)],
['NFL game report','Super Bowl LIX final','Philadelphia 40, Kansas City 22','Verified as reported',source(HURTS)],
['NFL game report','Jalen Hurts, Super Bowl LIX','17 completions / 22 attempts; 221 passing yards; 2 passing TD','Verified as reported',source(HURTS)],
['NFL game report','Travis Kelce, Super Bowl LIX','4 catches; 6 targets; 39 receiving yards','Verified as reported',source(KELCE)],
['NFL injury report','2026 regular-season week 7','', 'Page title and in-page week differ; do not ingest as a snapshot',source(INJURY)],
]
evidence = '<div class="callout"><b>Scope of review.</b> These are individually checked examples, not a complete NFL data set. Values are transcribed from the linked NFL pages and checked on 01 Nov 2026 UTC; season aggregates and single-game examples cannot validate a betting strategy.</div>' + section('01 / VERIFIED EXTRACTS','Evidence library','Every row links to the publishing authority.') + table(['PUBLISHER','SUBJECT','REPORTED VALUE','REVIEW','OFFICIAL SOURCE'],evidence_rows) + section('02 / SOURCE MAP','Potential inputs','Source availability is not equivalent to a timestamped historical feed.') + table(['INPUT','USE','LIMITATION','OFFICIAL SOURCE'],[
['NFL statistics','Results and player outcomes','Aggregates alone cannot support pregame training snapshots.',source(NFL)],
['NFL injury reports','Availability information','Current pages can change; preserve the version available at decision time.',source(INJURY)],
['NFL schedule','Event and timing context','Flex changes mean published schedules should be timestamped.',source(SCHEDULE)],
['National Weather Service','Forecasts and observations','Archive forecasts as issued; U.S. coverage does not automatically cover international games or indoor conditions.',source(WEATHER)],
['Sportsbook contract terms','Price and settlement','No verified historical executable quotes or rules have been collected.',''],
]) + '''<p class="caption">The sportsbook row is intentionally missing a link because no official provider has been established. See the <a href="review.html">review register</a>.</p>'''
# A missing source link is not permitted in a table row: link to regulator as context, not as provider evidence.
evidence = evidence.replace("<td>Sportsbook contract terms</td><td>Price and settlement</td><td>No verified historical executable quotes or rules have been collected.</td><td></td>", f'<td>Sportsbook contract terms</td><td>Price and settlement</td><td>No verified historical executable quotes or rules have been collected; regulator guidance is context only.</td><td>{source(RULES, "Regulator context ↗")}</td>')
evidence = evidence.replace('The sportsbook row is intentionally missing a link because no official provider has been established.', 'The sportsbook row links to regulator context, not a verified sportsbook quote.')

review_rows = [
['R01','No official, timestamped historical odds or settlement rules','No market baseline, executable price, backtest ROI or edge can be verified. All remain blank.','Obtain and archive licensed official operator quotes and terms.',source(RULES)],
['R02','No complete point-in-time NFL dataset','No trained model, automatic collection, signal or live line has been established.','Build and audit a reproducible as-of dataset from official sources.',source(NFL)],
['R03','No measured dependence','Correlation, sample size and joint-event probabilities remain blank.','Collect paired official game-level data and run the stated protocol.',source(NIST)],
['R04','No validated leaderboard or rewards','All candidates are pending; rankings, scores and rewards do not exist.','Complete all gates on matched, locked out-of-sample data.',source(METRIC)],
['R05','Injury page metadata mismatch','The linked page title says Week 8 while the in-page heading says WEEK 7; the URL ends in reg7.','Do not use the page as an as-of snapshot until reconciled.',source(INJURY)],
['R06','Repository and deployment','The initial repository contained only README.md; a static site is not an ingestion or prediction service. Pages deployment must be verified after merge.','Verify the live deployment and track operational failures.',source(PAGES)],
]
review = '<div class="callout"><b>Open by design.</b> A flag records a limitation, not a confirmed defect in an external source. Linked sources may supply context rather than directly verify a missing value.</div>' + section('01 / OPEN ITEMS','Flagged for review','These items do not imply a recommendation to bet.') + table(['ID','IRREGULARITY','IMPACT','NEXT STEP','OFFICIAL CONTEXT'],review_rows) + '''<div class="prose"><h3>Responsible use</h3><p>Sports outcomes remain uncertain; forecasts and past performance do not guarantee returns. Gambling can cause financial and other harms. Check applicable local law, avoid chasing losses, and use only money you can afford to lose. '''+source(HARM,'Gambling Commission research ↗')+'''</p></div>'''

pages = [ ('index.html','Overview','An evidence-first research desk for NFL forecasting.',home),('strategies.html','Strategies','Candidate signals for singles, parlays and player prop combinations.',strategies),('validation.html','Validation','The gates between an interesting idea and a credible strategy.',validation),('correlation.html','Correlation','A careful approach to dependence, not an assumption of independence.',correlation),('evidence.html','Evidence library','Official sources, carefully scoped observations and a transparent audit trail.',evidence),('review.html','Flagged for review','The unanswered questions and irregularities behind the research.',review) ]
for filename,title,subtitle,body in pages:
    (ROOT / filename).write_text(layout(filename,title,subtitle,body), encoding='utf-8')
print(f'Built {len(pages)} pages')
